nta.declaration:
/*** MAP BOUNDARIES & CONSTANTS ***/
const int MAX_X = 17;         // Rightmost boundary
const int MAX_Y = 12;         // Upmost bboundary (home bays)
const int INITIAL_X = 9;      // Initial x coordinate (could be theoretically set to any valid value)
const int INITIAL_Y = 0;      // Initial y coordinate (could be theoretically set to any empty row)

/*** TIMERS (1 time unit = 0.1s) ***/
const int INITIAL_TIMEOUT = 300;     // 30s game timer
const int TIMEOUT_REDUCTION = 20;    // 2s reduction for level
const int RESPAWN_DELAY = 20;        // 2s initial delay    
const int MOVE_DELAY = 1;            // 1s inter-move delaay to prevent Zeno behaviour
const int MAX_OBJECT_SPEED = 10;     // Maximum speed for any object
const int EMERGED_TIME = 100;        // 10s emerged time for diving turtles
const int SUBMERGING_TIME = 50;      // 5s submerging time for diving turtles
const int SUBMERGED_TIME = 100;      // 10s submerged time for diving turtles
const int EMERGING_TIME = 50;        // 5s emerging time for diving turtles
const int TOTAL_DIVE_CYCLE = EMERGED_TIME + SUBMERGING_TIME + SUBMERGED_TIME + EMERGING_TIME;

/*** SCORING ***/
const int MOVE_SCORE = 1;
const int BAY_FILLED_SCORE = 5;
const int LEVEL_WON_SCORE = 100;
const int LIVES = 5;

/*** DIRECTIONS ***/
typedef int[0, 3] Direction;
const Direction UP = 0;
const Direction DOWN = 1;
const Direction LEFT = 2;
const Direction RIGHT = 3;

/*** STRATEGY SELECTOR ***/
/* 
 * SMC NOTE: This array-based selector allows the verifier to test multiple 
 * probabilistic weight distributions without altering the underlying automata.
 * STRATEGY_SMART (2) also enables a heuristic look-ahead guard in attempt_move().
 */
// Define strategy IDs
const int STRATEGY_BASELINE = 0; // 5-2-2-1 (Blind Random Walk)
const int STRATEGY_WEIGHTS  = 1; // 8-1-1-0 (Blind Forward Bias)
const int STRATEGY_SMART    = 2; // 8-1-1-0 (Forward Bias + Hazard Radar)

// ---> SET ACTIVE STRATEGY <---
const int ACTIVE_STRATEGY = STRATEGY_SMART;

// Map the weights to the strategies [Baseline, Weights, Smart]
const int arr_up_weight[3]    = {5, 8, 8};
const int arr_left_weight[3]  = {2, 1, 1};
const int arr_right_weight[3] = {2, 1, 1};
const int arr_down_weight[3]  = {1, 0, 0};

/*** WEIGHT OF MOVEMENTS ***/
// UPPAAL will automatically assign these based on the ACTIVE_STRATEGY selected above
const int UP_WEIGHT    = arr_up_weight[ACTIVE_STRATEGY];
const int DOWN_WEIGHT  = arr_down_weight[ACTIVE_STRATEGY];
const int LEFT_WEIGHT  = arr_left_weight[ACTIVE_STRATEGY];
const int RIGHT_WEIGHT = arr_right_weight[ACTIVE_STRATEGY];


/*** FROGGER VARIABLES ***/
// Frogger coordinates
int[-1, MAX_X + 1] frog_x = INITIAL_X;
int[-1, MAX_Y + 1] frog_y = INITIAL_Y;

// Lives, score and home bays
int[0, LIVES] lives = LIVES;
int score = 0;
int[0, 5] home_bays_filled = 0;
bool bay_occupied[5] = {false, false, false, false, false};

/*** CHANNELS ***/
urgent broadcast chan die; // Sender: GameEngine -- Receiver: Frogger

/*** CONFIGURATION BLUEPRINTS ***/

// Generic moving entity configuration (vehicle/log/turtle)
typedef struct {
    int size;
    int speed; // This is used as 1/speed rate of exponential for Trucks
    bool is_diving;
} EntityConfig;

// Types of vehicles (can be theoretically initialized with different values, as long as speed <= MAX_OBJECT_SPEED)
const EntityConfig ORANGE  = {1, 3, false};
const EntityConfig DOZER   = {1, 10, false};
const EntityConfig GREEN   = {1, 5, false};
const EntityConfig PURPLE  = {1, 4, false};
const EntityConfig TRUCK   = {2, 7, false};

// Types of floatings (can be theoretically initialized with different values, as long as speed <= MAX_OBJECT_SPEED)
const EntityConfig LOG_S   = {3, 2, false};
const EntityConfig LOG_M   = {9, 7, false};
const EntityConfig LOG_L   = {5, 2, false};
const EntityConfig DIVT_3  = {5, 6, true};  // 3 diving turtles (total 5 spaces)
const EntityConfig DIVT_2  = {3, 2, true};  // 2 diving turtles (total 3 spaces)
const EntityConfig TURT_3  = {5, 6, false}; // 3 turtles (total 5 spaces)
const EntityConfig TURT_2  = {3, 2, false}; // 2 turtles (total 5 spaces)

/*** ACTIVE ENTITIES ***/

// Entity
typedef struct {
    int[-1, MAX_X + 1] x;
    int[0, MAX_Y] y;
    int[0, MAX_OBJECT_SPEED] move_timer;
    int[0, TOTAL_DIVE_CYCLE] dive_timer;
    bool submerged;
    EntityConfig type; 
} ActiveEntity;

// Number of vehicles and floats (can be edited as long as enough vehicles and floats are then used)
const int NUM_VEHICLES = 12;
const int NUM_FLOATS = 10;

ActiveEntity vehicles[NUM_VEHICLES] = {
    {4, 1, 0, 0, false, ORANGE}, {14, 1, 0, 0, false, ORANGE},     
    {2, 2, 0, 0, false, DOZER}, {11, 2, 0, 0, false, DOZER},       
    {4, 3, 0, 0, false, GREEN}, {8, 3, 0, 0, false, GREEN}, {13, 3, 0, 0, false, GREEN}, {17, 3, 0, 0, false, GREEN}, 
    {2, 4, 0, 0, false, PURPLE}, {10, 4, 0, 0, false, PURPLE},     
    {4, 5, 0, 0, false, TRUCK}, {15, 5, 0, 0, false, TRUCK}        
};

ActiveEntity floats[NUM_FLOATS] = {
    {5, 7, 0, 0, false, TURT_3}, {13, 7, 0, 0, false, DIVT_3},                             
    {7, 8, 0, 0, false, LOG_S}, {11, 8, 0, 0, false, LOG_S}, {15, 8, 0, 0, false, LOG_S},    
    {3, 9, 0, 0, false, LOG_M},                                                        
    {2, 10, 0, 0, false, TURT_2}, {10, 10, 0, 0, false, DIVT_2},                        
    {1, 11, 0, 0, false, LOG_L}, {1, 11, 0, 0, false, LOG_L}                            
};


/*** GAME LOGIC FUNCTIONS ***/

/**
 * @brief Centralized game engine tick. Updates all vehicles and floats based on their 
 *        individual speed timers. Handles continuous movement, torus wrapping for 
 *        entities and Frogger, and dive timer progression for turtles.
 * @param None
 * @return void
 */
void update_game() {
    int i;

    // VEHICLE MOVEMENT
    for (i = 0; i < NUM_VEHICLES; i++) {
        // Skip Trucks for SMC; they use their own stochastic template
        if (vehicles[i].type.size != TRUCK.size) {
            vehicles[i].move_timer++;
            if (vehicles[i].move_timer >= vehicles[i].type.speed) {

                if (vehicles[i].y % 2 != 0) { // Right to Left
                    if (vehicles[i].x == -1) vehicles[i].x = MAX_X + 1; 
                    else vehicles[i].x--;
                } else { // Left to Right
                    if (vehicles[i].x == MAX_X + 1) vehicles[i].x = -1; 
                    else vehicles[i].x++;
                }

                vehicles[i].move_timer = 0; // Reset safely
            }
        }
    }

    // FLOATINGS MOVEMENT
    for (i = 0; i < NUM_FLOATS; i++) {
        floats[i].move_timer++;

        // MOVEMENT & CARRYING FROGGER
        if (floats[i].move_timer >= floats[i].type.speed) {
            int dist = (frog_x - floats[i].x + (MAX_X + 3)) % (MAX_X + 3);
            bool carrying = (frog_y == floats[i].y && dist < floats[i].type.size);

            if (floats[i].y == 8 || floats[i].y == 9 || floats[i].y == 11) { // Left to Right
                // Move Log
                if (floats[i].x == MAX_X + 1) floats[i].x = -1; // Pac-Man logic with 2 box "delay"
                else floats[i].x++;

                // Move Frogger
                if (carrying) {
                    if (frog_x == MAX_X + 1) frog_x = -1;       // Pac-Man logic with 2 box "delay"
                    else frog_x++;
                }
            } else { // Right to Left
                // Move Log
                if (floats[i].x == -1) floats[i].x = MAX_X + 1; // Pac-Man logic with 2 box "delay"
                else floats[i].x--;

                // Move Frogger
                if (carrying) {
                    if (frog_x == -1) frog_x = MAX_X + 1;       // Pac-Man logic with 2 box "delay"
                    else frog_x--;
                }
            }
            floats[i].move_timer = 0; // Reset movement timer
        }

        // DIVING LOGIC
        if (floats[i].type.is_diving) {
            floats[i].dive_timer++;
            floats[i].submerged = (floats[i].dive_timer > (SUBMERGING_TIME + EMERGED_TIME) && floats[i].dive_timer < TOTAL_DIVE_CYCLE);
            if (floats[i].dive_timer >= TOTAL_DIVE_CYCLE) floats[i].dive_timer = 0; // Reset dive cycle
        }
    }
}

/**
 * @brief Evaluates if a vehicle occupies a specific coordinate on the map.
 *        Uses parameterized modulo arithmetic to safely evaluate wrapped coordinates 
 *        on the Torus ring, supporting vehicles of any size across the map boundaries.
 * @param x The x-coordinate to evaluate.
 * @param y The y-coordinate to evaluate.
 * @return true if a vehicle occupies the cell, false otherwise.
 */
bool vehicle_at(int x, int y) {
    int i;
    for (i = 0; i < NUM_VEHICLES; i++) {
        if (vehicles[i].y == y) {
            int dist = (x - vehicles[i].x + (MAX_X + 3)) % (MAX_X + 3);
            if (dist < vehicles[i].type.size) return true;
        }
    }
    return false;
}

/**
 * @brief Evaluates if a valid, non-submerged floating platform exists at a specific coordinate.
 *        Uses parameterized modulo arithmetic to safely evaluate wrapped coordinates on the Torus ring.
 * @param x The x-coordinate to evaluate.
 * @param y The y-coordinate to evaluate.
 * @return true if a safe platform occupies the cell, false otherwise.
 */
bool platform_at(int x, int y) {
    int i;
    for (i = 0; i < NUM_FLOATS; i++) {
        if (!floats[i].submerged && floats[i].y == y) {
            int dist = (x - floats[i].x + (MAX_X + 3)) % (MAX_X + 3);
            if (dist < floats[i].type.size) return true;
        }
    }
    return false;
}

/**
 * @brief Determines if Frogger's current y-coordinate places him inside the river zone.
 * @param None
 * @return true if Frogger is in the river, false otherwise.
 */
bool is_in_river() {
    return (frog_y >= 7 && frog_y <= 11);
}

/**
 * @brief Comprehensive safety check. Determines if Frogger's exact position triggers a death condition
 *        (hit by vehicle, drowning in river without a platform, or smashing into the wall between bays).
 * @param None
 * @return true if the current position is lethal, false if safe.
 */
bool is_deadly() {
    if (vehicle_at(frog_x, frog_y)) return true;
    if (is_in_river() && !platform_at(frog_x, frog_y)) return true;    
    if (frog_y == MAX_Y && (frog_x % 4 >= 2)) return true;
    return false;
}

/*** STATISTICAL TRACKERS ***/
/*
 * SMC NOTE: These variables do not affect game logic. They act as telemetry 
 * trackers to calculate expected values (E[<=1000]) for death causes and progression.
 */
int stat_hit_by_vehicle = 0;
int stat_drowned = 0;
int stat_timeout = 0;
int stat_total_lifespan = 0;

template.declaration:
/**
 * @brief Updates the stochastic truck's position.
 *        Trucks are located on Row 5 (an odd row), so they move Right to Left.
 *        Wraps around using the corrected [-1, MAX_X + 1] Torus boundary.
 * @param None
 * @return void
 */
void update_truck() {
    // Right-to-Left movement with the updated 2-space Torus delay
    if (vehicles[id].x == -1) {
        vehicles[id].x = MAX_X + 1; 
    } else {
        vehicles[id].x--;
    }
}

clock game_timer;            
clock move_timer;    
int level = 1;
int current_timeout = INITIAL_TIMEOUT;

/**
 * @brief Resets Frogger to his starting coordinates at the bottom center of the map.
 *        Called upon initialization and after losing a life or scoring.
 * @param None
 * @return void
 */
void reposition() {
    frog_x = INITIAL_X;
    frog_y = INITIAL_Y;
}

/**
 * @brief Checks if Frogger is currently positioned safely inside an empty home bay.
 * @param None
 * @return true if Frogger occupies a home bay cell, false otherwise.
 */
bool is_home_bay() {
    return (frog_y == MAX_Y && (frog_x % 4 < 2));
}

/**
 * @brief Executes a probabilistic movement attempt by Frogger.
 *        Moves into the wall between bays are allowed so the state engine can 
 *        properly process the death condition via is_deadly().
 * @param dir The direction Frogger is attempting to move (UP, DOWN, LEFT, RIGHT).
 * @return void
 */
void attempt_move(Direction dir) {
    int new_x = frog_x;
    int new_y = frog_y;

    // Constraint: Cannot move voluntarily if currently in the off-screen wrap zone
    if (frog_x < 0 || frog_x > MAX_X) return;

    if (dir == UP) new_y++;
    if (dir == DOWN) new_y--;
    if (dir == LEFT) new_x--;
    if (dir == RIGHT) new_x++;

    // --- STRATEGY: HEURISTIC AWARENESS ---
    if (ACTIVE_STRATEGY == STRATEGY_SMART) {
        // Do not jump if a car is currently occupying the destination
        if (vehicle_at(new_x, new_y)) return;

        // Do not jump if destination is the river AND there is no platform there
        if (new_y >= 7 && new_y <= 11 && !platform_at(new_x, new_y)) return;
    }

    // Constraint: Can only jump within visible map boundaries
    if (new_x >= 0 && new_x <= MAX_X && new_y >= 0 && new_y <= MAX_Y) {

        // Constraint: Prevent jumping into an already occupied home bay
        if (new_y == MAX_Y && (new_x % 4 < 2) && bay_occupied[new_x / 4]) {
            return; // Move blocked
        }

        // Apply the verified move
        frog_x = new_x;
        frog_y = new_y;

        // Score is only awarded for forward progress
        if (dir == UP) score += MOVE_SCORE; 
    }
}

/**
 * @brief Handles the transition to a new level. Awards points, increments the level,
 *        reduces the global timeout, clears all home bays, and resets Frogger.
 * @param None
 * @return void
 */
void complete_level() {
    int i;
    score += LEVEL_WON_SCORE;
    level++;

    // Calculate new timeout: 30s - 2s*(level-1)
    current_timeout = INITIAL_TIMEOUT - (TIMEOUT_REDUCTION * (level - 1));

    // Safety cap: Prevent the timeout from dropping below 2 seconds
    if (current_timeout < 20) current_timeout = 20; 

    // Clear all home bays
    for (i = 0; i < 5; i++) {
        bay_occupied[i] = false;
    }
    home_bays_filled = 0;

    reposition();
}

/**
 * @brief Identifies the exact cause of death and increments the telemetry trackers.
 *        Called when reaching the 'Dead' state.
 * @param None
 * @return void
 */
void record_death_cause() {
    /* 
     * SMC NOTE: game_timer is a continuous clock. UPPAAL strictly forbids adding 
     * continuous clocks to discrete integers. fint() is used to cast the float 
     * value to an integer before addition.
     */
    stat_total_lifespan += fint(game_timer);

    if (vehicle_at(frog_x, frog_y)) {
        stat_hit_by_vehicle++;
    } else if (is_in_river() && !platform_at(frog_x, frog_y)) {
        stat_drowned++;
    }
}

nta.system:
// Instantiate the stochastic trucks (indices 10 and 11 in the vehicles array)
Truck1 = Truck(10);
Truck2 = Truck(11);

// SMC System Initialization
system Frogger, GameEngine, Truck1, Truck2;
